runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync,gunzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-recover25-20261122',require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:[...registry.allowedDomains,'lite.cnn.com'],siteCooldown:false,maxWireRequests:12}),r={at:new Date().toISOString(),samples:[],archived:[]};fs.mkdirSync(root+'/evidence',{recursive:true});const norm=s=>String(s||'').normalize('NFC').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\s+/g,' ').trim();
function inspect(html,url){const $=ch.load(html),schema=[];for(const e of $('script[type="application/ld+json"]').toArray())try{const v=JSON.parse($(e).text());schema.push(...(Array.isArray(v)?v:[v]));}catch{}const article=schema.find(a=>a['@type']==='NewsArticle'),body=$('article.article--lite').clone();body.find('.source--lite,script,style,nav,footer,form').remove();const paragraphs=body.find('p.paragraph--lite').toArray().map(e=>norm($(e).text())).filter(Boolean),original=norm(article?.articleBody),missing=paragraphs.filter(p=>!original.includes(p));return {url,title:$('h2.headline').text().trim(),canonical:$('link[rel="canonical"]').attr('href'),datePublished:article?.datePublished,dateModified:article?.dateModified,flag:article?.isAccessibleForFree,hasPart:article?.hasPart,restrictedSelectorPresent:$('.article__content').length,liteBodyCount:$('article.article--lite').length,bodyChars:norm(body.text()).length,schemaChars:original.length,paragraphCount:paragraphs.length,missingParagraphs:missing.length,missingChars:missing.reduce((n,p)=>n+p.length,0),missingPreviews:missing.slice(0,2).map(p=>p.slice(0,120)),wordCount:article?.wordCount,scripts:$('script[src]').toArray().map(e=>$(e).attr('src')).filter(s=>!/google|adservice|analytics|gstatic/.test(s)).slice(-12),visibleGate:$('form[action*="login"],.paywall-message,[data-paywall],.regwall,[class*="regwall"]:not(script)').length};}
const old=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-alt25-20261122/cnn-samples.json'));for(const s of old.samples){const html=gunzipSync(fs.readFileSync(s.file)).toString();r.archived.push(inspect(html,s.url));}
try{for(const url of ['https://lite.cnn.com/',...old.samples.slice(0,5).map(s=>s.url)]){const p=await driver.get('qc-recover25-cnn-proof',url,registry.sources.get('edition.cnn.com').config,[],{reviewFailed:true,taskRole:'article'}),o={url,statusCode:p.statusCode,error:p.error,proxyId:p.proxyId};if(!p.error&&p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));o.proof=inspect(p.html,url);}r.samples.push(o);console.log(JSON.stringify({...o,proof:o.proof?{...o.proof,scripts:undefined}:undefined}));}r.finishedAt=new Date().toISOString();fs.writeFileSync(root+'/cnn-public-proof.json',JSON.stringify(r,null,2));}finally{await network.close();}
